let rrvvfoManifest;
await test('Rrvvfo atlas manifest loads with normalized anchors',async()=>{const response=await fetch('../assets/fighters/rrvvfo/rrvvfo-animations.json');assert(response.ok,'manifest request failed');rrvvfoManifest=await response.json();assert(validateSpriteManifest(rrvvfoManifest),'manifest validation failed');assert(rrvvfoManifest.atlas.frameCanvas.join('x')==='192x192','frame canvas is not normalized');for(const [name,frame] of Object.entries(rrvvfoManifest.frames)){assert(frame.groundPivot[0]===96&&frame.groundPivot[1]===178,`${name} has an inconsistent ground pivot`);assert(frame.projectileOrigin.length===2,`${name} has no projectile anchor`) }});
await test('Rrvvfo sprite paths are GitHub Pages relative',()=>{assert(isRepositoryRelativePath(rrvvfoManifest.image),'atlas image path is root-relative');for(const path of Object.values(rrvvfoManifest.effects))assert(isRepositoryRelativePath(path),`${path} is unsafe for project Pages`)});
await test('idle and run sprite animations loop',()=>{const atlas=new SpriteAtlas(rrvvfoManifest,{},new URL('../assets/fighters/rrvvfo/rrvvfo-animations.json',location.href)),animator=new SpriteAnimator(atlas);animator.play('idle',{restart:true});animator.update(5000);assert(!animator.complete&&animator.name==='idle','idle did not loop');animator.play('run',{priority:ANIMATION_PRIORITY.movement,restart:true});animator.update(5000);assert(!animator.complete&&animator.name==='run','run did not loop')});
await test('non-looping attack animation completes and returns control',()=>{const atlas=new SpriteAtlas(rrvvfoManifest,{},new URL('../assets/fighters/rrvvfo/rrvvfo-animations.json',location.href)),completed=[],animator=new SpriteAnimator(atlas,{onComplete:name=>completed.push(name)});animator.play('light1',{priority:ANIMATION_PRIORITY.attack,restart:true});animator.update(1000);assert(animator.complete&&completed[0]==='light1','attack animation never completed');assert(animator.play('idle',{priority:ANIMATION_PRIORITY.idle}),'idle could not resume after completion')});
await test('animation priority lets hurt interrupt movement but not idle interrupt attack',()=>{const atlas=new SpriteAtlas(rrvvfoManifest,{},new URL('../assets/fighters/rrvvfo/rrvvfo-animations.json',location.href)),animator=new SpriteAnimator(atlas);animator.play('run',{priority:ANIMATION_PRIORITY.movement});assert(animator.play('hurtLight',{priority:ANIMATION_PRIORITY.hurt}),'hurt did not interrupt movement');animator.play('light1',{priority:ANIMATION_PRIORITY.attack,restart:true});assert(!animator.play('idle',{priority:ANIMATION_PRIORITY.idle}),'idle interrupted an unfinished attack')});
await test('Rrvvfo light chain chooses light1 light2 light3 in order',()=>{const{one}=pair();const names=[];for(let hit=0;hit<3;hit++){one.attackCd=one.windup=0;assert(one.attack('light'),'light did not start');names.push(one.visualAction);one.windup=0;one.resolveAttack()}assert(names.join(',')==='light1,light2,light3',`visual chain was ${names.join(',')}`);assert(one.chainLockout>0,'visual mapping bypassed combo termination')});
await test('heavy launcher and air attacks map to dedicated animations',()=>{const ground=pair();ground.one.attack('heavy');assert(resolveRrvvfoAnimation(ground.one,ground.world).name==='heavyStartup','heavy startup animation missing');ground.one.cancelStartup();ground.one.attackCd=0;ground.one.attack('launcher');assert(resolveRrvvfoAnimation(ground.one,ground.world).name==='launcherStartup','launcher animation missing');const air=pair();air.one.grounded=0;air.one.y-=50;air.one.attack('air');assert(resolveRrvvfoAnimation(air.one,air.world).name==='airLight','air light animation missing');air.one.cancelStartup();air.one.attackCd=0;air.one.attack('airHeavy');assert(resolveRrvvfoAnimation(air.one,air.world).name==='airHeavy','air heavy animation missing')});
await test('block perfect-block and guard-break animations are distinct',()=>{const setup=pair();setup.two.block=1;assert(resolveRrvvfoAnimation(setup.two,setup.world).name==='blockStart','block pose missing');setup.two.visualPerfectTimer=6;assert(resolveRrvvfoAnimation(setup.two,setup.world).name==='perfectBlock','perfect-block pose missing');setup.two.visualPerfectTimer=0;setup.two.guardBreakStun=20;assert(resolveRrvvfoAnimation(setup.two,setup.world).name==='guardBreak','guard-break pose missing')});
await test('Fire Blast manifest provides a hand projectile origin',()=>{for(const frameName of rrvvfoManifest.animations.fireBlastFire.frames){const anchor=rrvvfoManifest.frames[frameName].projectileOrigin;assert(anchor[0]>96&&anchor[1]<178,`${frameName} projectile anchor is not near the forward hand`) }});
await test('Shots of Agony keeps four separate clone visuals and synchronized fire',()=>{const{world,one}=pair();world.timers=new ManualTimers();one.en=100;assert(one.beginShotsOfAgony(),'Shots did not start');const clones=world.effects.effects.filter(effect=>effect.t==='agonyClone');assert(clones.length===4,'clone visuals were not four separate instances');assert(new Set(clones.map(effect=>effect.volleyId)).size===1,'clone visuals did not share one volley');world.timers.flush();const projectiles=world.projectiles.filter(projectile=>projectile.volleyId===one.agonyVolleyId);assert(projectiles.length===4&&one.agonyCooldown===300,'four projectiles did not fire together with the original cooldown')});
await test('Lens visuals preserve exact gameplay cost and dodge state',()=>{const{one,two}=pair();one.hp=40;one.en=100;assert(one.lensAbility(),'Lens did not activate');assert(one.hp===1&&one.en===10&&one.visualAction==='lensActivate','Lens visual changed its HP or energy cost');one.hit(20,0,'heavy',two,{hitstun:20});assert(['lensDodgeLeft','lensDodgeRight'].includes(one.visualAction),'Lens dodge visual was not selected');assert(one.hp===1,'automatic dodge took damage')});
await test('Object Swap selects disappearance and reappearance without changing movement rules',()=>{const{one}=pair();const start=one.x;one.en=100;one.dash();assert(one.x!==start&&one.visualAction==='objectSwapDisappear','Object Swap visual or movement did not start');one.visualActionTimer=8;assert(resolveRrvvfoAnimation(one,one.world).name==='objectSwapReappear','Object Swap did not enter reappearance')});
await test('sprite visual preference and hood variant persist',()=>{const storage=memoryStorage(),settings={...defaultRrvvfoVisualSettings(),enabled:true,appearance:'up',quality:'reduced'};assert(saveRrvvfoVisualSettings(settings,storage),'settings did not save');const loaded=loadRrvvfoVisualSettings(storage);assert(storage.data[RRVVFO_VISUAL_SAVE_KEY]&&loaded.enabled&&loaded.appearance==='up'&&loaded.quality==='reduced','sprite toggle or hood variant did not persist')});
await test('disabled or missing sprites safely retain legacy visuals',async()=>{const disabled=new FighterVisuals({settings:{...defaultRrvvfoVisualSettings(),enabled:false}});assert(!(await disabled.preloadForMatch(['rrvvfo'])).ready,'disabled sprites loaded unexpectedly');const missing=new FighterVisuals({settings:{...defaultRrvvfoVisualSettings(),enabled:true},manifestUrl:new URL('../assets/fighters/rrvvfo/missing.json',location.href).href});const result=await missing.preloadForMatch(['rrvvfo']);assert(!result.ready&&missing.status==='fallback','missing asset did not enter fallback state')});
await test('round and Training cleanup clear visual-only state',()=>{const setup=pair();setup.world.fighterVisuals={resetFighter:fighter=>{fighter.__visualReset=true}};setup.one.visualAction='ultimateAttack';setup.one.visualActionTimer=99;setup.one.resetRuntime();assert(setup.one.__visualReset&&!setup.one.visualAction&&!setup.one.visualActionTimer,'fighter reset retained visual state');trainingState.enabled=true;resetTrainingWorld(setup.world);assert(setup.world.projectiles.length===0&&setup.world.effects.effects.length===0,'Training cleanup retained transient visuals')});

const failed=results.filter(result=>!result.pass),output=results.map(result=>`${result.pass?'PASS':'FAIL'}  ${result.name}${result.error?` — ${result.error}`:''}`).join('\n');
document.getElementById('results').textContent=`${output}\n\n${results.length-failed.length}/${results.length} passing`;document.getElementById('results').className=failed.length?'fail':'pass';
window.__SMOKE_RESULTS__={results,passed:results.length-failed.length,failed:failed.length};
if(failed.length)console.error('Smoke tests failed',failed);else console.info(`Smoke tests passed: ${results.length}`);
